INSERT INTO `disaster_reports` (`id`, `tracking_code`, `barangay_id`, `purok_name`, `coordinates_lat`, `coordinates_lng`, `incident_location`, `disaster_type`, `severity`, `urgency`, `aid_support`, `affected_families`, `affected_individuals`, `displaced_families`, `casualties_count`, `injuries_count`, `missing_count`, `requested_assistance`, `situation_overview`, `resolution_notes`, `status`, `submitted_by`, `created_at`, `updated_at`, `completed_at`) VALUES 
(1,'REQ-2026-001',12,'Purok Riverside 1',8.246800,124.258800,'Riverside Corridor Lowland','Flash Flood','Critical','Immediate','both',350,1540,220,0,4,0,'Requesting urgent dispatch of 350 Family Food Packs, 200 Hygiene Kits, 2 Inflatable Rescue Boats with operators, and 60 Life Vests due to rising Mandulog River overflow.','Mandulog river level reached 4.2 meters (Red Warning Stage). Water has entered low-lying residential clusters in Purok Riverside 1. 220 families evacuated to Hinaplanon NHS Gym.',NULL,'Ongoing',2,'2026-10-14 06:30:00','2026-10-18 22:37:08',NULL),
(2,'REQ-2026-002',38,'Purok 1 Baybay',8.214800,124.237200,'Coastal Seawall Sector','Storm Surge','High','High','resources',180,790,95,0,1,0,'Requesting 180 Family Food Packs, 100 Hygiene Kits, 50 Modular Tents, and First Aid replenishment for coastal evacuees.','High tide coupled with localized squall caused 1.8-meter sea swells battering coastal households along Purok 1 Baybay.',NULL,'Ongoing',3,'2026-10-14 08:15:00','2026-10-18 22:37:08',NULL),
(3,'REQ-2026-003',12,'Purok San Miguel',8.245500,124.259800,'Lower Commercial & Residential Basin','Flood','Moderate','Medium','both',90,395,25,0,0,0,'Pre-emptive prepositioning of 90 Food Packs and 2 Portable Water Pumps in case creek drainage overflows.','Heavy continuous rain recorded over the hinterlands. Creek drainage in Purok San Miguel experiencing sluggish runoff.',NULL,'Ongoing',2,'2026-10-15 10:20:00','2026-10-18 22:37:08',NULL),
(4,'REQ-2026-004',12,'Purok Baybay',8.251500,124.254200,'Hinaplanon Coastal Frontage','Storm Surge','High','High','both',140,620,65,0,1,0,'Requesting 140 Family Food Packs, 70 Modular Tents, and Emergency Cash Assistance for displaced shoreline fisherfolk families.','Strong coastal wave action breached the secondary breakwater, affecting beachside residential structures.',NULL,'Ongoing',2,'2026-10-15 14:45:00','2026-10-18 22:37:08',NULL),
(5,'REQ-2026-005',12,'Purok Sambag',8.249800,124.262000,'Mandulog River Bend Basin','Flash Flood','Critical','Immediate','both',210,950,130,0,2,0,'Urgent rescue support needed: 210 Food Packs, 120 Hygiene Kits, 1 Rescue Boat, and Financial Calamity Aid.','Mandulog tributary overflowed during midnight flash flood. Mud silt and swift currents trapped households in the inner loop.',NULL,'Ongoing',2,'2026-10-16 02:15:00','2026-10-18 22:37:08',NULL),
(6,'REQ-2026-006',12,'Purok Katipunan',8.249000,124.258000,'Katipunan Creek Embankment','Flood','Moderate','Medium','resources',75,330,15,0,0,0,'75 Family Food Packs and 40 Hygiene Kits requested for pre-emptive evacuees.','Localized creek overflow due to clogged culverts during torrential downpour.','Culverts declogged by barangay maintenance team. Floodwater subsided completely. Relief packs distributed.','Completed',2,'2026-10-10 09:00:00','2026-10-18 22:37:08','2026-10-11 17:00:00'),
(7,'REQ-2026-007',12,'Purok Centro',8.246200,124.261800,'Purok Centro Public Market Vicinity','Fire','High','Immediate','both',45,190,45,0,3,0,'Immediate emergency shelter, 45 modular tents, food packs, and emergency cash assistance for burned residential block.','Residential fire broke out due to faulty electrical connection in dense housing cluster.','Fire extinguished by BFP. All 45 displaced families received modular tents and emergency aid.','Completed',2,'2026-10-08 13:20:00','2026-10-18 22:37:08','2026-10-09 18:00:00'),
(8,'REQ-2026-008',35,'Purok Gumamela',8.224200,124.234000,'Iligan Riverbank Embankment','Flood','Critical','High','resources',110,490,60,0,0,0,'Requesting 110 Food Packs, 50 Hygiene Kits, and 200 Sandbags for riverbank erosion defense.','Iligan River water level rising rapidly. Riverbank soil erosion threatening 60 residential houses.',NULL,'Ongoing',8,'2026-10-16 11:30:00','2026-10-18 22:37:08',NULL),
(9,'REQ-2026-009',21,'Purok Mandulog Bridge Area',8.244800,124.305200,'Mandulog Highway Slopes','Landslide','Critical','Immediate','resources',160,710,90,0,5,0,'Heavy rescue equipment, chainsaws, 160 food packs, trauma first aid kits, and heavy machinery support.','Rain-induced landslide covered 2 lanes of highway and pushed mud into 30 residential homes.',NULL,'Ongoing',1,'2026-10-16 15:40:00','2026-10-18 22:37:08',NULL),
(10,'REQ-2026-010',12,'Purok Orchids',8.242000,124.260500,'Lowland Wetland Fringe','Flash Flood','High','High','both',85,380,35,0,0,0,'85 Food Packs, 50 Hygiene Kits, and Cash Assistance for displaced wetland families.','Flash flood from swollen upland creek inundated 35 homes up to knee-deep.','Floodwaters drained into Mandulog outlet. Families safely returned home after cleaning operations.','Completed',2,'2026-10-12 08:30:00','2026-10-18 22:37:08','2026-10-13 16:30:00');
