INSERT INTO `recommendations` (`id`, `recommendation_code`, `disaster_request_id`, `priority`, `modality`, `confidence_score`, `decision_path`, `recommendation_reason`, `financial_aid_recommended_budget`, `financial_aid_approved_budget`, `financial_aid_per_family`, `financial_aid_target_families`, `financial_aid_source`, `financial_aid_added_type`, `financial_aid_allocation_id`, `status`, `reviewed_by`, `reviewed_at`, `review_remarks`, `created_at`) VALUES 
(1,'REC-2026-001',1,'Critical','both',93.80,'Root [Disaster: Flood] -> Branch [Severity: Critical (Water Depth > 1.5m)] -> Branch [Population: 350 Families] -> Branch [Urgency: Immediate] -> Stock Feasibility Check [Central Depot: Food Packs 1200 >= 350; Rescue Boats 12 >= 2; PFDs 450 >= 60; Hygiene Kits 850 >= 200] -> Outcome: Tier-1 Flood Assistance Package Activated.','Model evaluated disaster conditions: River overflow in Purok Riverside 1 (Mandulog watershed), critical severity with 350 affected families (220 displaced). Recommends 1:1 family food pack ration for immediate 3-day buffer, 2 water rescue craft, 60 life vests, 200 hygiene kits, and emergency financial assistance.',1750000.00,1750000.00,5000.00,350,'LGU Calamity Fund (QRF)','ai_recommended',NULL,'Approved',1,'2026-10-14 07:00:00','Approved by ICDRRMO Operations Head. Prioritized convoy clearance to Hinaplanon.','2026-10-14 06:45:00'),
(2,'REC-2026-002',2,'High','resources',89.20,'Root [Disaster: Storm Surge] -> Branch [Severity: High (Coastal Inundation)] -> Branch [Population: 180 Families] -> Branch [Urgency: High] -> Stock Feasibility Check [Food Packs: 180; Hygiene Kits: 100; Modular Tents: 50] -> Outcome: Tier-2 Coastal Displacement Package.','Based on coastal surge impact displacing 95 families into Tomas Cabili Central School, the model recommends 180 food packs, 100 hygiene kits, and 50 modular privacy tents to safeguard evacuees.',0.00,0.00,0.00,0,'LGU Calamity Fund (QRF)','ai_recommended',NULL,'Approved',1,'2026-10-14 09:00:00','Authorized dispatch from Depot Bay A & Bay B.','2026-10-14 08:30:00'),
(3,'REC-2026-003',3,'','both',86.50,'Root [Disaster: Flood] -> Branch [Severity: Moderate (Creek Ponding)] -> Branch [Population: 90 Families] -> Branch [Urgency: Medium] -> Stock Feasibility Check [Food Packs: 90; Water Pumps: 2] -> Outcome: Precautionary Prepositioning Package.','Precautionary allocation for Purok San Miguel lowlands to mitigate potential overflow. Includes 90 family food packs and 2 high-capacity portable drainage pumps.',450000.00,450000.00,5000.00,90,'LGU Calamity Fund (QRF)','ai_recommended',NULL,'Approved',1,'2026-10-15 11:00:00','Approved for standby deployment at Barangay Covered Court.','2026-10-15 10:40:00'),
(4,'REC-2026-004',4,'High','both',91.00,'Root [Disaster: Storm Surge] -> Branch [Severity: High (Seawall Breach)] -> Branch [Population: 140 Families] -> Branch [Urgency: High] -> Stock Feasibility Check [Food Packs: 140; Modular Tents: 70; Cash Grant: Verified] -> Outcome: Coastal Relief & Livelihood Protection Tier.','Purok Baybay coastal surge impact requires 140 family food packs, 70 modular tents, and emergency cash assistance of PHP 4,000 per family for urgent shelter repairs.',560000.00,560000.00,4000.00,140,'DSWD Assistance to Individuals in Crisis (AICS)','ai_recommended',NULL,'Pending Review',NULL,NULL,NULL,'2026-10-15 15:00:00'),
(5,'REC-2026-005',5,'Critical','both',94.50,'Root [Disaster: Flash Flood] -> Branch [Severity: Critical (Swift Inundation)] -> Branch [Population: 210 Families] -> Branch [Urgency: Immediate] -> Stock Feasibility Check [Food Packs: 210; Rescue Boats: 1; PFDs: 40; Hygiene Kits: 120] -> Outcome: Emergency Flash Flood Tier-1 Response.','Urgent recommendation for Purok Sambag river bend flash flood: 210 food packs, 120 hygiene kits, 1 inflatable rescue craft with operator crew, 40 life vests, and cash assistance of PHP 3,000 per family.',630000.00,630000.00,3000.00,210,'LGU Calamity Fund (QRF)','ai_recommended',NULL,'Pending Review',NULL,NULL,NULL,'2026-10-16 02:45:00');
